import random
def gen(country,pairs,label_unit,label_cap,extra=()):
    """pairs: list of (unit, capital). Makes unit->capital and capital->unit questions with distractors from other pairs."""
    out=[]
    units=[u for u,_ in pairs]; caps=[c for _,c in pairs]
    for u,c in pairs:
        rnd=random.Random(hash(country+u)%10**6)
        wrongc=[x for x in dict.fromkeys(caps) if x!=c]; rnd.shuffle(wrongc)
        if c!=u: out.append((f"ما {label_cap} {label_unit} {u} في {country}؟",[c]+wrongc[:3]))
        wrongu=[x for x in units if x!=u]; rnd.shuffle(wrongu)
        if c!=u: out.append((f"{label_unit} {u} ما {label_cap}؟" if False else f"أي {label_unit} في {country} {label_cap} {c}؟".replace('{label_cap} ','')) if False else (f"{c} هي {label_cap} أي {label_unit} في {country}؟",[u]+wrongu[:3]))
    return out
def city_in(country,pairs,unit_word):
    out=[]; units=sorted({u for _,u in pairs})
    for city,u in pairs:
        rnd=random.Random(hash(country+city)%10**6)
        w=[x for x in units if x!=u]; rnd.shuffle(w)
        out.append((f"في أي {unit_word} تقع منطقة {city} في {country}؟",[u]+w[:3]))
    return out
